#!/bin/bash
# Mac test of the Mac panel's own layout on iPadOS 18 and of its wiring (1.8.1 item 1; common/CC18MacLayout.h, statusbar/CC18Shape.h, CC18Tiles.h, ccmodule/).
set -e
cd "$(dirname "$0")"
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
clang -O2 -fobjc-arc -Wall -Wno-unused-function -framework Foundation -o "$W/t" test-cc18maclayout.m
"$W/t"
fails=0
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fails=1; fi; }
Q=../statusbar/CC18Shape.h
T=../statusbar/CC18Tiles.h
P=../statusbar/CCPanel.h
check "the store's hook: only Apple's Control Center layout file, only with Mac in force and its rows here; Apple's file otherwise" \
  "grep -F '{ \"SBIconModelPropertyListFileStore\", \"initWithIconStateURL:desiredIconStateURL:\", \"@32@0:8@16@24\", (void *)DMCC18StoreInit, (void **)&o_DMCC18StoreInit,' $Q | grep -q 'kDMCC18PartTiles },\$' \
   && awk '/^static id DMCC18StoreInit\(.*\{\$/{f=1} f&&/if \(gCC18On && gCC18HaveTiles && \[current isKindOfClass:\[NSURL class\]\] && \[current.path isEqualToString:kMSBDCC18AppleLayoutFile\]\) \{/{a=1} f&&a&&/return o_DMCC18StoreInit\(self, _cmd, current, desired\);/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok"
check "  ... made once, from the user's, never over one already there; a failure leaves Apple's file; never written to Apple's own file" \
  "awk '/^static NSURL \*DMCC18MacLayoutURL\(void\) \{/{f=1} f&&/if \(step == kMSBDCC18MacFileUse\) return \[NSURL fileURLWithPath:mac\];/{a=1} f&&a&&/MSBDCC18MacLayoutFrom\(state, 8,/{b=1} f&&b&&/\[out writeToFile:mac options:NSDataWritingAtomic \| NSDataWritingFileProtectionNone error:nil\]/{c=1} f&&c&&/return ok \? \[NSURL fileURLWithPath:mac\] : nil;/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok && ! grep -q 'writeToFile:kMSBDCC18AppleLayoutFile' $Q"
check "  ... a style change while running, in Apple's steps for a layout changed under a live Control Center: saved and clean first (never the old layout in the other file), off the root folder, the new store, -layout (not -reloadIcons: that only reloads icons), on the new root folder, its controller given it" \
  "awk '/^static void DMCC18LayoutFollowsStyle\(UIViewController \*m\) \{/{f=1} f&&/saveIconStateIfNeeded/{a=1} f&&a&&/isIconStateDirty\"\)\)\) \{.*return; \}/{b=1} f&&b&&/@\"setDelegate:\"\), nil\);/{c=1} f&&c&&/@\"removeFolderObserver:\"\), paging\);/{d=1} f&&d&&/@\"setStore:\"\), fresh\);/{e=1} f&&e&&/NSSelectorFromString\(@\"layout\"\)\);/{g=1} f&&g&&/@\"addFolderObserver:\"\), paging\);/{h=1} f&&h&&/@\"setDelegate:\"\), paging\);/{i=1} f&&i&&/@\"setFolder:\"\), newRoot\);/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok \
   && ! awk '/^static void DMCC18LayoutFollowsStyle\(UIViewController \*m\) \{/{f=1} f&&/@\"reloadIcons\"/{print; exit} f&&/^}/{exit}' $Q | grep -q . \
   && awk '/^static void DMCC18ApplyStyle\(.*\{\$/{f=1} f&&/DMCC18LayoutFollowsStyle\(/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok"
check "the part's rows are optional: without them, the panel as before (the store's hook left out)" \
  "grep -qF 'else if (kDMCC18Hooks[i].part == kDMCC18PartTiles) { tiles = NO; [gCC18CheckOptional addObject:line]; }' $Q && grep -qF 'else if (r->part == kDMCC18PartTiles) { tiles = NO; [gCC18CheckOptional addObject:line]; }' $Q && grep -qF '(part == kDMCC18PartTiles && !gCC18HaveTiles)' $Q"
check "the tiles' panel calls go to 18's host only on 18 (a module of ours asked for its host, never on 15-17: the four are not registered there)" \
  "grep -qF 'if (kind < 0 || kind > 3 || [NSProcessInfo processInfo].operatingSystemVersion.majorVersion != 18) return nil;' $T && grep -qF 'static BOOL DMCC18TilesAreOurs(void) { return gCC18TilesMade; }' $T \
   && [ \$(grep -c 'if (DMCC18TilesAreOurs())' $P) = 4 ] && grep -qF '{ kMSBDCCMacConnectivityID, kMSBDCCMacTilesDir, @\"MacConnectivity.bundle\", \"MacConnectivity\", NO, 18 },' ../common/CCModuleList.h"
check "the host's function is exported under the name the bundles ask for; the crash guard knows the bundles and the file" \
  "grep -qF '#define kMSBDCCMacTileHostFn \"MSBDCCMacTileHost\"' ../common/CCModuleList.h && grep -q '__attribute__((visibility(\"default\"))) UIViewController \*MSBDCCMacTileHost(int kind)' $T && grep -qF 'dlsym(RTLD_DEFAULT, kMSBDCCMacTileHostFn)' ../ccmodule/MSBDMacTileModule.h \
   && for b in MacConnectivity MacDisplay MacSound MacNowPlaying; do grep -qxF \"image \$b part\" crashmap-rules.txt || exit 1; done; grep -qxF 'file MacStatusBarCore ^CC18Tiles\\.h\$ controlcenter' crashmap-rules.txt"
check "each bundle: its principal class and identifier as its Info.plist says, its own size class bits" \
  "for s in 'Connectivity MacConnectivity mac-connectivity kMSBDCCMacConnectivitySizes' 'Display MacDisplay mac-display kMSBDCCMacSliderSizes' 'Sound MacSound mac-sound kMSBDCCMacSliderSizes' 'NowPlaying MacNowPlaying mac-nowplaying kMSBDCCMacNowPlayingSizes'; do set -- \$s; P2=../ccmodule/MacTileResources/\$1/Info.plist; M=../ccmodule/MSBDMac\$1Module.m; grep -q \"<string>MSBDMac\$1Module</string>\" \$P2 && grep -q \"<string>\$2</string>\" \$P2 && grep -q \"com.besiktasliseba.macstatusbaranddock.\$3<\" \$P2 && grep -q \"#define MSBD_MAC_TILE_SIZES \$4\" \$M || exit 1; done"
check "  ... read only with our modules in the repository (MacCCGrabber's word, checked before the file is used or made): else nothing of it is touched" \
  "awk '/^static NSURL \*DMCC18MacLayoutURL\(void\) \{/{f=1} f&&/dlsym\(RTLD_DEFAULT, kMSBDCCRegisteredControlsFn\)/{a=1} f&&a&&/NSArray \*controls = registered \? registered\(\) : nil;/{g=1} f&&g&&/BOOL sshInstalled = access\(kMSBDSSHDaemon, F_OK\) == 0;/{h=1} f&&h&&/if \(!MSBDCC18MacLayoutReadable\(have, controls, sshInstalled\)\) \{.*return nil; \}/{b=1} f&&b&&/MSBDCC18MacFileStep\(/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok \
   && grep -qF '#define kMSBDCCRegisteredControlsFn \"MSBDCCRegisteredControls\"' ../common/CCModuleList.h && grep -qF '__attribute__((visibility(\"default\"))) NSArray<NSString *> *MSBDCCRegisteredControls(void) { return gMSBDCCHooked == 3 ? gMSBDCCIdentifiers : nil; }' ../macsettings/CCGrabber.x"
check "each bundle's class adopts Control Center's protocol (its loader takes no other: the tile stayed a blank placeholder), its content view controller too" \
  "grep -qF '@interface MSBD_MAC_TILE_CLASS : NSObject <CCUIContentModule>' ../ccmodule/MSBDMacTileModule.h && grep -qF '@protocol CCUIContentModule <NSObject>' ../ccmodule/MSBDMacTileModule.h && grep -qF '@interface DMCC18TileHost : UIViewController <CCUIContentModuleContentViewController>' $T"
check "the Mac tiles are never given RAM & CPU's note (CCTileKeep.h: one note per control, the layout it watches is iPadOS's)" \
  "awk '/^%ctor/{f=1} f&&/if \(MSBDCCIsMacTile\(mid\)\) continue;/{a=1} f&&a&&/\[kept addObject:mid\]; \[notes addObject:/{b=1} f&&b&&/MSBDCCTileKeepStartAll\(kMSBDCCTileStateFile, notes, kept, log\);/{print \"ok\"; exit}' ../macsettings/CCGrabber.x | grep -q ok"
check "\"Add a Control\" offers the Mac tiles only with the Mac layout in force (the instance manager's list, the status bar part's word; both ways of the layout set it)" \
  "grep -qF 'return inForce && inForce() ? all : MSBDCCWithoutMacTiles(all);' ../common/CCModuleRegister.h && grep -qF 'MSHookMessageEx(im, lq, (IMP)MSBDCCLoadable, (IMP *)&gMSBDCCOrigLoadable);' ../common/CCModuleRegister.h \
   && grep -qF '__attribute__((visibility(\"default\"))) BOOL MSBDCCMacLayoutInForce(void) { return gCC18MacLayoutInForce; }' $Q && grep -qF 'gCC18MacLayoutInForce = YES;' $Q && grep -qF 'gCC18MacLayoutInForce = [want.path isEqualToString:kMSBDCC18MacLayoutFile];' $Q && grep -qF '#define kMSBDCCMacLayoutInForceFn \"MSBDCCMacLayoutInForce\"' ../common/CCModuleList.h"
check "the gallery: Settings' icon stays on SSH's section alone (two sections of one app made Apple's sheet throw); our Mac tiles' sections as one, made again with their picture" \
  "grep -qF \"for (id m in modules) if ([m isEqual:kMSBDCCModuleID] || [m isEqual:kMSBDCCSSHModuleID]) return m;\" ../statusbar/AppLibraryApps.h && grep -qF \"} else if ([ours isEqualToString:kMSBDCCSSHModuleID]) {\" ../statusbar/AppLibraryApps.h \
   && grep -qF \"if (!icon && MSBDCCGallerySectionIsMacTiles(modules)) {\" ../statusbar/AppLibraryApps.h && grep -qF 'DMALHook(@\"CCUIPagingViewController\", @\"customApplicationWidgetCollectionsForControlsGalleryViewController:\", @\"@@:@\", (IMP)DMALGalleryMerged, (IMP *)&o_DMALGalleryMerged);' ../statusbar/AppLibraryApps.h"
check "a Now Playing tile's tap area comes from its layout (the 2 x 2 size); 15-17's frame is the same numbers" \
  "grep -qF '    _info.frame = DMCCTAt(L.info);' ../statusbar/CCTiles.h && grep -qF 'L.info = CGRectMake(0.0, 0.0, L.play.origin.x, h);' ../common/CCTileLogic.h"
check "Display's chevron and a hold on 18: its page in the panel (Apple's module is no tile of the Mac layout); 15-17's path stays Apple's module, then Settings" \
  "grep -qF 'if (![self dm_display] || DMCC18TilesAreOurs()) { DMCCPanelOpenDetail(self); return; }' ../statusbar/CCTiles.h && grep -qF 'if ([self dm_display] && !DMCC18TilesAreOurs()) return nil;' ../statusbar/CCTiles.h \
   && grep -qF 'if (DMCC18TilesAreOurs()) { [self dm_details]; return; }' ../statusbar/CCTiles.h && grep -qF 'BOOL opened = DMCCPanelExpandModule(self.module);' ../statusbar/CCTiles.h && grep -qF 'DMOpenURL(@\"prefs:root=DISPLAY\", @\"display settings\");' ../statusbar/CCTiles.h"
check "  ... its rows as Apple's own module sets them, each only where its shape is as read: the arbiter's toggle, Night Shift's -setEnabled:withOption: 3, True Tone's -setEnabled:" \
  "awk '/^static NSArray \*DMCC18DisplayRows\(void\) \{/{f=1} f&&/DMCCTypes\(arbiter, @\"toggleCurrentStyle\", \"v16@0:8\"\)/{a=1} f&&a&&/\"B24@0:8\^\{\?=BBBi\{\?=\{\?=ii\}\{\?=ii\}\}QB\}16\"/{b=1} f&&b&&/@\"setEnabled:withOption:\"\), on, 3\)/{c=1} f&&c&&/DMCCTypes\(tone, @\"setEnabled:\", \"B20@0:8B16\"\)/{print \"ok\"; exit} f&&/^}/{exit}' $T | grep -q ok"
check "the tile on 18 draws for the dark material in both appearances (Apple's container, no white-on-white, no black-on-dark)" \
  "awk '/^@implementation DMCC18TileHost/{f=1} f&&/self.view.overrideUserInterfaceStyle = UIUserInterfaceStyleDark;/{a=1} f&&a&&/self.tile = DMCCTMakeTileForRole\(self.role\);/{print \"ok\"; exit} f&&/^@end/{exit}' $T | grep -q ok"
check "Apple's module from a tile: its tile on the page shown expands; on another page that page is shown (its own numbering, not the list's place); none in the layout: NO" \
  "awk '/^static BOOL DMCC18AppleModuleOpen\(NSString \*mid\) \{/{f=1} f&&/@\"pageIndexForIconListModel:\"\), list\);/{a=1} f&&a&&/if \(page != /{b=1} f&&b&&/@\"setCurrentPageIndex:animated:\"\), page, YES\);/{c=1} f&&c&&/@\"expandModuleWithIdentifier:\"\), mid\);/{print \"ok\"; exit} f&&/^}/{exit}' $T | grep -q ok"
check "a page in the panel: Esc closes it first, Control Center closing closes it, the back row closes it, one at a time (none over edit mode or Apple's expanded module)" \
  "grep -qF 'if (DMCC18PagePanelEscape()) {' $Q && grep -qF 'if (gCCPDetail) DMCCPanelCloseDetail(NO);   // (one of our pages open as it closed: CC18Tiles.h)' $Q \
   && grep -qF '[back addAction:[UIAction actionWithHandler:^(__kindof UIAction *a) { DMCC18PageClose(YES); }] forControlEvents:UIControlEventTouchUpInside];' $T && grep -qF 'if (!tile || gCCPDetail || !gCC18On || !gCC18Shown || gCC18Editing || gCC18Expanded ||' $T"
check "the crash guard (review 1.8.1, 7): a crash in this file or in the gallery's section of the Mac tiles sets Control Center Style back to iPadOS's, the switch that really takes them away" \
  "grep -qxF 'file MacStatusBarCore ^(CC18Shape|CC18MacLayout)\\.h\$ controlcenter' crashmap-rules.txt && [ \$(grep -nxF 'sym MacStatusBarCore ^_*DMAL(GalleryMerged|MacTiles[A-Z]) controlcenter' crashmap-rules.txt | cut -d: -f1) -lt \$(grep -nxF 'sym MacStatusBarCore ^_*DMAL[A-Z] actmonLibrary' crashmap-rules.txt | cut -d: -f1) ]"
check "  ... iPadOS's style has nothing of it: the hook only passes through without the Mac layout in force, whatever the sections say; the section keeps a range of its own in a release build" \
  "awk '/^static id DMALGalleryMerged\\(id self, SEL _cmd, id gallery\\) \\{/{f=1} f&&/id all = o_DMALGalleryMerged\\(self, _cmd, gallery\\);/{a=1} f&&a&&/if \\(!MSBDCCMacLayoutInForce\\(\\) \\|\\| !\\[all isKindOfClass:\\[NSArray class\\]\\]\\) return all;/{print \"ok\"; exit} f&&/^}/{exit}' ../statusbar/AppLibraryApps.h | grep -q ok && grep -qF '__attribute__((noinline)) static id DMALMacTilesSection(id section, NSArray *items, id vendor) {' ../statusbar/AppLibraryApps.h"
check "  ... a Mac layout that is there but cannot be read now (before a first unlock, say) is not written over: Apple's file for that while" \
  "awk '/^static NSURL \*DMCC18MacLayoutURL\(void\) \{/{f=1} f&&/int step = MSBDCC18MacFileStep\(d \|\| \[\[NSFileManager defaultManager\] fileExistsAtPath:mac\], have\);/{a=1} f&&a&&/if \(step == kMSBDCC18MacFileAppleForNow\) \{.*return nil; \}/{b=1} f&&b&&/MSBDCC18MacLayoutFrom\(state, 8,/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok"
check "  ... the first one is not made while the crash guard has RAM & CPU or SSH off (review 1.8.1, 5): asked before Apple's file is read, Apple's file for that while" \
  "awk '/^static NSURL \*DMCC18MacLayoutURL\(void\) \{/{f=1} f&&/if \(!MSBDCC18MacLayoutMayBeMade\(controls, sshInstalled\)\) \{.*return nil; \}/{a=1} f&&a&&/d = \[NSData dataWithContentsOfFile:kMSBDCC18AppleLayoutFile\];/{b=1} f&&b&&/MSBDCC18MacLayoutFrom\(state, 8,/{print \"ok\"; exit} f&&/^}/{exit}' $Q | grep -q ok"
[ $fails = 0 ] && echo "test-cc18maclayout: wiring checks pass" || { echo "test-cc18maclayout: wiring checks FAILED"; exit 1; }
